#!/usr/bin/env node
/**
 * THE CIPHER MUSEUM — Minified-bundle freshness check
 * Pages ship .min.js files generated by scripts/build-min.js. This test
 * re-minifies each source in memory and fails if the committed .min.js
 * differs — i.e. someone edited a source and forgot `npm run build:js`.
 */
'use strict';

const fs = require('fs');
const path = require('path');
const { minify } = require('terser');

const ROOT = path.join(__dirname, '..');

// Keep in sync with scripts/build-min.js.
const TARGETS = [
  'js/ciphers/all-engines.js',
  'js/demo-loader.js',
  'js/artifact-cards-data.js',
];
const OPTIONS = { compress: true, mangle: true };

let fail = 0;

(async () => {
  console.log('━━━ Minified bundle freshness ━━━\n');
  for (const rel of TARGETS) {
    const minRel = rel.replace(/\.js$/, '.min.js');
    const minPath = path.join(ROOT, minRel);
    if (!fs.existsSync(minPath)) {
      console.log(`  ❌  ${minRel} missing — run: npm run build:js`);
      fail++;
      continue;
    }
    const source = fs.readFileSync(path.join(ROOT, rel), 'utf8');
    const expected = (await minify(source, OPTIONS)).code;
    const actual = fs.readFileSync(minPath, 'utf8');
    if (expected === actual) {
      console.log(`  ✅  ${minRel} is current`);
    } else {
      console.log(`  ❌  ${minRel} is STALE — run: npm run build:js`);
      fail++;
    }
  }
  console.log(`\n  ${fail === 0 ? '✅ All minified bundles current' : '❌ ' + fail + ' stale bundle(s)'}`);
  process.exit(fail > 0 ? 1 : 0);
})().catch((e) => { console.error(e); process.exit(1); });
